        // JUSPRIN_HARNESS_REQUEST_OUT=<file> keeps the whole body to read.
        if (const char* out = std::getenv("JUSPRIN_HARNESS_REQUEST_OUT"); out != nullptr && *out != '\0')
            std::ofstream(out, std::ios::binary) << body;
    }

