    call_entry.tool           = "workspace_inspect";
    call_entry.arguments_json = "{}";
    call_entry.output_json    = R"({"state":"succeeded"})";
    return {{"assistant", "Earlier answer"}, {"user", "Make it strong."}, call_entry, {"assistant", "It is set up."}};
}

