TEST_CASE("a finished turn opens the next as it was sent while the host's history only adds its replay", "[agent][loop][cache]")
{
    Harness h;
    finish_turn(h, chat_request("Make it strong."), "call-1");
    AgentRequest next   = chat_request("Thanks.");
    next.conversation   = replayed_first_turn();

    SECTION("the replay of the turn is replaced by the turn")
    {
        REQUIRE(h.agent->start(next));
        const json body = h.last_body();
        CHECK(body["opening"] == json::array({json{{"role", "assistant"}, {"text", "Earlier answer"}}}));
        CHECK(body["carried"] == json::array({json{{"user", "Make it strong."}, {"steps", 2}}}));
        CHECK(body["user"][0]["text"] == "Thanks.");
    }

    SECTION("turns keep being carried while the history grows only by their replays")
    {
        AgentConversationContext second_call;
        second_call.call_id        = "call-2";
        second_call.tool           = "workspace_inspect";
        second_call.arguments_json = "{}";
        second_call.output_json    = R"({"state":"succeeded"})";
        finish_turn(h, next, "call-2");
        AgentRequest third = chat_request("And now?");
        third.conversation = replayed_first_turn();
        third.conversation.insert(third.conversation.end(), {{"user", "Thanks."}, second_call, {"assistant", "Done."}});
        REQUIRE(h.agent->start(third));
        CHECK(h.last_body()["carried"].size() == 2);
        CHECK(h.last_body()["opening"].size() == 1);
    }

    SECTION("a title request between turns does not lose the turn")
    {
        AgentRequest title = chat_request("");
        title.purpose      = AgentRequest::Purpose::ConversationTitle;
        REQUIRE(h.agent->start(title));
        h.fake->data(frame(json{{"text", "A title"}}));
        h.fake->data(frame(json{{"turn", "titled"}}));
        REQUIRE(h.poll_until(AgentEventKind::Completed));
        REQUIRE(h.agent->start(next));
        CHECK(h.last_body()["carried"].size() == 1);
    }

    SECTION("anything else in the history is sent as the host replays it")
    {
        SECTION("another chat") { next.conversation_id = "other-chat"; }
        SECTION("an earlier entry changed, as a trim or a restore changes it") { next.conversation[0].text = "Trimmed"; }
        SECTION("a note between the turns") { next.conversation.push_back({"developer", "The person changed the filament."}); }
        SECTION("a call the turn did not make") { next.conversation[2].call_id = "call-9"; }
        SECTION("a second person's message") { next.conversation.push_back({"user", "Hello?"}); }
        SECTION("other instructions") { next.session.instructions = "You are someone else."; }
        REQUIRE(h.agent->start(next));
        CHECK(h.last_body()["carried"].empty());
        CHECK(h.last_body()["opening"].size() == next.conversation.size());
    }
}

