// An Anthropic service that answers each reply request with the next
// scripted stream, at once, and keeps every body it was sent. A title
// request is answered with a title and takes nothing from the script.
class ScriptedAnthropicTransport final : public IAgentHttpTransport
{
public:
    bool post(AgentHttpRequest request, EventFn event) override
    {
        json body = json::parse(request.body);
        const bool title = !body.contains("tools");
        std::string stream = kTitleStream;
        if (!title) {
            REQUIRE(!streams.empty());
            stream = std::move(streams.front());
            streams.pop_front();
            replies.push_back(std::move(body));
        }
        event(AgentHttpEvent{AgentHttpEvent::Kind::Data, std::move(stream), {}, 0});
        event(AgentHttpEvent{AgentHttpEvent::Kind::Complete, {}, {}, 200});
        return true;
    }
    void cancel() override {}

    static std::string sse(const json& event) { return "data: " + event.dump() + "\n\n"; }

    // One response: its thinking, its words, then a call if it makes one.
    static std::string response(const std::string& text, const std::string& call_id = {}, const std::string& tool = {},
                                const json& input = json::object())
    {
        std::string out = sse(json{{"type", "message_start"},
                                   {"message", json{{"id", "msg"}, {"usage", json{{"input_tokens", 100}, {"output_tokens", 1}}}}}});
        out += sse(json{{"type", "content_block_start"}, {"index", 0},
                        {"content_block", json{{"type", "thinking"}, {"thinking", ""}, {"signature", ""}}}});
        out += sse(json{{"type", "content_block_delta"}, {"index", 0}, {"delta", json{{"type", "thinking_delta"}, {"thinking", "Hm."}}}});
        out += sse(json{{"type", "content_block_delta"}, {"index", 0}, {"delta", json{{"type", "signature_delta"}, {"signature", "sig"}}}});
        out += sse(json{{"type", "content_block_stop"}, {"index", 0}});
        out += sse(json{{"type", "content_block_start"}, {"index", 1}, {"content_block", json{{"type", "text"}, {"text", ""}}}});
        out += sse(json{{"type", "content_block_delta"}, {"index", 1}, {"delta", json{{"type", "text_delta"}, {"text", text}}}});
        out += sse(json{{"type", "content_block_stop"}, {"index", 1}});
        if (!call_id.empty()) {
            out += sse(json{{"type", "content_block_start"}, {"index", 2},
                            {"content_block", json{{"type", "tool_use"}, {"id", call_id}, {"name", tool}, {"input", json::object()}}}});
            out += sse(json{{"type", "content_block_delta"}, {"index", 2},
                            {"delta", json{{"type", "input_json_delta"}, {"partial_json", input.dump()}}}});
            out += sse(json{{"type", "content_block_stop"}, {"index", 2}});
        }
        out += sse(json{{"type", "message_delta"}, {"delta", json{{"stop_reason", call_id.empty() ? "end_turn" : "tool_use"}}},
                        {"usage", json{{"output_tokens", 10}}}});
        return out + sse(json{{"type", "message_stop"}});
    }

    inline static const std::string kTitleStream = response("A strong part");

    std::deque<std::string> streams;
    std::vector<json>       replies;
};

// A request's messages less their cache breakpoints, which move to the
// newest message on every request and are not part of what is cached.
json without_breakpoints(json value)
{
    if (value.is_object()) {
        value.erase("cache_control");
        for (auto& [key, child] : value.items())
            child = without_breakpoints(child);
    } else if (value.is_array()) {
        for (json& child : value)
            child = without_breakpoints(child);
    }
    return value;
}

void run_turn(Harness& harness, const std::string& text, const std::string& client_id)
{
    harness.send_user_message(text, client_id);
    for (int i = 0; i < 10; ++i) {
        harness.pump_all();
        pump_tools_to_completion(harness);
    }
}

} // namespace

TEST_CASE("a turn's first request repeats the previous turn's requests as they were sent", "[agent][cache]")
{
    auto transport = std::make_unique<ScriptedAnthropicTransport>();
    ScriptedAnthropicTransport* service = transport.get();
    service->streams = {ScriptedAnthropicTransport::response("Let me look.", "toolu_1", "workspace_inspect",
                                                             json{{"sections", json::array({"summary"})}}),
                        ScriptedAnthropicTransport::response("It is set up."),
                        ScriptedAnthropicTransport::response("You are welcome.")};
    Harness harness(make_provider_agent(*profile_for("anthropic"), "key", "claude-opus-5-5", "", std::move(transport), {}));
    harness.handshake();

    run_turn(harness, "Make it strong.", "c-carry-1");
    REQUIRE(service->replies.size() == 2);
    run_turn(harness, "Thanks.", "c-carry-2");
    REQUIRE(service->replies.size() == 3);

    // The provider reads back from its cache only a request's unchanged
    // opening, so everything the turn before sent must open this one as it
    // was sent: its thinking, the workspace beside the person's words, the
    // call's result as the codec wrote it.
    const json before = without_breakpoints(service->replies[1]);
    const json after  = without_breakpoints(service->replies[2]);
    CHECK(after["system"] == before["system"]);
    CHECK(after["tools"] == before["tools"]);
    const json& earlier = before["messages"];
    const json& later   = after["messages"];
    REQUIRE(later.size() > earlier.size());
    for (std::size_t i = 0; i < earlier.size(); ++i) {
        INFO("message " << i);
        CHECK(later[i] == earlier[i]);
    }
    // The previous turn's last response follows, then this turn's words.
    CHECK(later[earlier.size()]["role"] == "assistant");
    CHECK(later[earlier.size()]["content"][1]["text"] == "It is set up.");
    CHECK(later.back()["role"] == "user");
    CHECK(later.back()["content"][0]["text"] == "Thanks.");
}
